entries[52712] = { ["name"] = "Ferngesteuertes Feuerwerk", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Befestigt das ferngesteuerte Feuerwerk an der wilden Glucke.\n\"Einfach an einer wilden Glucke festmachen, und ab geht's!\"" }
entries[52714] = { ["name"] = "Zwergische Gewehrkugel", ["text"] = "Questgegenstand\nEinzigartig\n\"Von dem Durchschlag durch Ganns Rippen verformt.\"" }
entries[52715] = { ["name"] = "Schlächterbotsteuerungsdingens", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Setzt einen Schlächterbot ein, um Körperteile von einem getöten Tier zu ernten. (2 Sek. Abklingzeit)" }
entries[52716] = { ["name"] = "Zwielichtfeuerlanze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand\n1 - 2 Schaden Geschwindigkeit 3.00\n(0.5 Schaden pro Sekunde)\nHaltbarkeit 16 / 16\n\"Die Klinge ist aus reinem Feuer geschmiedet, doch der Griff aus Drachenhaut fühlt sich noch immer kühl an.\"\nVerkaufspreis:" }
entries[52717] = { ["name"] = "Feurige Leine", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Beschwört die Brut von Loderos. (20 Sek. Abklingzeit)" }
entries[52718] = { ["name"] = "Geringe himmlische Essenz", ["text"] = "Benutzen: Macht aus drei geringen himmlischen Essenzen eine große Essenz.\nHandwerksmaterial" }
entries[52719] = { ["name"] = "Große himmlische Essenz", ["text"] = "Benutzen: Macht aus einer großen himmlischen Essenz drei geringe Essenzen.\nHandwerksmaterial" }
entries[52720] = { ["name"] = "Kleiner himmlischer Splitter", ["text"] = "Benutzen: Fügt 3 kleine himmlische Splitter zu einem himmlischen Splitter zusammen.\nHandwerksmaterial" }
entries[52721] = { ["name"] = "Himmlischer Splitter", ["text"] = "Handwerksmaterial" }
entries[52722] = { ["name"] = "Mahlstromkristall", ["text"] = "Handwerksmaterial" }
entries[52723] = { ["name"] = "Runenverzierte Elementiumrute", ["text"] = "Wird beim Aufheben gebunden\nWerkzeug für Verzauberkunst\n\"Kann auch wie jede geringere runenverzierte Rute verwendet werden.\"" }
entries[52724] = { ["name"] = "Kommuniqué des Schattenhammers", ["text"] = "Questgegenstand" }
entries[52725] = { ["name"] = "Schlachtpläne für den Hyjal", ["text"] = "Questgegenstand" }
entries[52726] = { ["name"] = "Steinblüte", ["text"] = "Questgegenstand\n\"Eine vertrocknete, ätzende Pilzblüte.\"" }
entries[52727] = { ["name"] = "Bitterblüte", ["text"] = "Questgegenstand\n\"Die Knospen dieser Pflanze sind schwer von der ihr innewohnenden Flüssigkeit.\"" }
entries[52728] = { ["name"] = "Schwarzfeuerglut", ["text"] = "Questgegenstand\n\"Fühlt sich kalt an, obwohl es noch brennt.\"" }
entries[52729] = { ["name"] = "Rekrutenrobe", ["text"] = "Wird beim Aufheben gebunden\nDauer: 1 StundeBrust Stoff\n1 Rüstung\nHaltbarkeit 55 / 55\nAnlegen: Verkleidet Euch als Mitglied des neuen Weltuntergangskults.\nVerkaufspreis:" }
entries[52730] = { ["name"] = "Reinigender Trunk", ["text"] = "Questgegenstand\n\"Das Gebräu ist noch warm und blubbert.\"" }
entries[52731] = { ["name"] = "Mekkadrills Rede", ["text"] = "Questgegenstand\nEinzigartig" }
entries[52733] = { ["name"] = "Formel: Waffe - Machtstrom", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Machtstrom' durchführt.\nEine Waffe dauerhaft verzaubern, sodass Eure Heilungen oder Schaden verursachenden Zauber manchmal Eure Intelligenz 12 Sek. lang um 19 erhöhen. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Verzauberkunst des Kataklysmus (75)" }
entries[52734] = { ["name"] = "Bruchstück", ["text"] = "Questgegenstand\n\"Dieses Bruchstück sieht aus, als sei es Teil eines Dreizacks gewesen.\"" }
entries[52735] = { ["name"] = "Formel: Waffe - Windwandler", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Windwandler' durchführt.\nEine Waffe dauerhaft verzaubern, sodass manchmal 10 Sek. lang Euer Ausweichen um 7922 und Eure Bewegungsgeschwindigkeit um 10% erhöht wird, wenn Ihr im Nahkampf zuschlagt. Diese Verzauberung ist mit passiven Erhöhungen der Bewegungsgeschwindigkeit stapelbar. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Verzauberkunst des Kataklysmus (75)" }
entries[52736] = { ["name"] = "Formel: Waffe - Erdrutsch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Erdrutsch' durchführt.\nEine Waffe dauerhaft verzaubern, sodass manchmal Eure Angriffskraft 12 Sek. lang um 6126 erhöht wird, wenn Ihr im Nahkampf zuschlagt. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Verzauberkunst des Kataklysmus (75)" }
entries[52737] = { ["name"] = "Formel: Umhang - Großer kritischer Trefferwert", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Großer kritischer Trefferwert' durchführt.\nEinen Umhang dauerhaft verzaubern, sodass der kritische Trefferwert um 6 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst des Kataklysmus (75)" }
entries[52738] = { ["name"] = "Formel: Armschiene - Großer kritischer Trefferwert", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Großer kritischer Trefferwert' durchführt.\nArmschienen dauerhaft verzaubern, sodass der kritische Trefferwert um 6 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst des Kataklysmus (75)" }
