entries[52789] = { ["name"] = "Rostiger Schädelschlüssel", ["text"] = "Questgegenstand\nEinzigartig\n\"Sieht aus, als hätte Gar'gol ihn regelmäßig benutzt, um sich die Ohren zu reinigen.\"" }
entries[52819] = { ["name"] = "Froststurmkristall", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Löscht die Flammen, die einen brennenden Bittsteller verzehren. (2 Sek. Abklingzeit)" }
entries[52828] = { ["name"] = "Kugel des Aufstiegs", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Beschwört eine Kugel des Aufstiegs und beginnt Eure geistige Ausbildung." }
