entries[52834] = { ["name"] = "Aufgeladenes Kondensatorglas", ["text"] = "Questgegenstand\n\"Ein verkorktes Glas mit einer Kupferspirale in seiner Mitte. Es sieht leer aus, aber wenn Ihr es in den Händen haltet, stehen Euch die Haare zu Berge.\"" }
entries[52835] = { ["name"] = "Elementargeräte", ["text"] = "Questgegenstand\n\"Kleine, tragbare Geräte, die mächtige Elementare beherbergen.\"" }
entries[52843] = { ["name"] = "Zwergenrunenstein", ["text"] = "\"Schlüsselstein, der archäologische Artefakte der Zwerge mit fehlenden Fragmenten vervollständigen kann.\"\nVerkaufspreis:" }
