entries[54068] = { ["name"] = "Weißes Wollrhinozeros", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares weißes Wollrhinozeros oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Toby \"der Märchenonkel\" Eisenbolz hat dieses Zotteltier in der Boreanischen Tundra entdeckt, das nicht sonderlich darüber erfreut ist, von einem Gnom gefangen worden zu sein.\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht" }
entries[54069] = { ["name"] = "Flammender Hippogryph", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren flammenden Hippogryphen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Hippogryphen sind hochintelligente, denkende Wesen und nicht nur einfache \"Reittiere\".\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht\nHandelsposten" }
